from collections.abc import Callable

import pytest


def wrapped(job: Callable[[], str]) -> str:
    """Return "start:" + job() + ":end".

    The helper itself performs no I/O, logging, or other side effects.
    The job is called exactly once, and any exception it raises propagates
    unchanged.
    """
    return "start:" + job() + ":end"


def test_wrapped_returns_framed_result() -> None:
    assert wrapped(lambda: "x") == "start:x:end"


def test_wrapped_empty_result() -> None:
    assert wrapped(lambda: "") == "start::end"


def test_wrapped_preserves_job_output_verbatim() -> None:
    assert wrapped(lambda: "a:b\nc") == "start:a:b\nc:end"


def test_wrapped_propagates_job_exception() -> None:
    def boom() -> str:
        raise RuntimeError("job failed")

    with pytest.raises(RuntimeError, match="job failed"):
        wrapped(boom)
